WITH `_src_normalized` AS (SELECT LOWER(TRIM(BOTH '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM `src`.`code`)) AS `code`, CASE WHEN LOWER(CASE WHEN `src`.`status` IN ('N/A', '') THEN NULL ELSE `src`.`status` END) = 'A' THEN 'Active' WHEN LOWER(CASE WHEN `src`.`status` IN ('N/A', '') THEN NULL ELSE `src`.`status` END) = 'I' THEN 'Inactive' WHEN LOWER(CASE WHEN `src`.`status` IN ('N/A', '') THEN NULL ELSE `src`.`status` END) = 'O\'Brien' THEN 'Quoted' ELSE LOWER(CASE WHEN `src`.`status` IN ('N/A', '') THEN NULL ELSE `src`.`status` END) END AS `status`, TRIM(BOTH '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM `src`.`city`) AS `city`, TRIM(LEADING '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM `src`.`first`) AS `first`, TRIM(TRAILING '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM `src`.`last`) AS `last`, CASE WHEN `src`.`score` IN (-1) THEN NULL ELSE `src`.`score` END AS `score` FROM `shop`.`orders_v1` AS `src`), `_tgt_normalized` AS (SELECT LOWER(TRIM(BOTH '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM `tgt`.`code`)) AS `code`, LOWER(CASE WHEN `tgt`.`status` IN ('N/A', '') THEN NULL ELSE `tgt`.`status` END) AS `status`, TRIM(BOTH '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM `tgt`.`city`) AS `city`, TRIM(LEADING '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM `tgt`.`first`) AS `first`, TRIM(TRAILING '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM `tgt`.`last`) AS `last`, CASE WHEN `tgt`.`score` IN (-1) THEN NULL ELSE `tgt`.`score` END AS `score` FROM `shop`.`orders_v2` AS `tgt`) SELECT `src`.`code` AS `_veridelta_key_0`, `src`.`status` AS `_veridelta_source_0`, `tgt`.`status` AS `_veridelta_target_0`, COALESCE(`src`.`status` <=> `tgt`.`status`, FALSE) AS `_veridelta_match_0`, `src`.`city` AS `_veridelta_source_1`, `tgt`.`city` AS `_veridelta_target_1`, COALESCE(`src`.`city` <=> `tgt`.`city`, FALSE) AS `_veridelta_match_1`, `src`.`first` AS `_veridelta_source_2`, `tgt`.`first` AS `_veridelta_target_2`, COALESCE(`src`.`first` <=> `tgt`.`first`, FALSE) AS `_veridelta_match_2`, `src`.`last` AS `_veridelta_source_3`, `tgt`.`last` AS `_veridelta_target_3`, COALESCE(`src`.`last` <=> `tgt`.`last`, FALSE) AS `_veridelta_match_3`, `src`.`score` AS `_veridelta_source_4`, `tgt`.`score` AS `_veridelta_target_4`, COALESCE(`src`.`score` <=> `tgt`.`score`, FALSE) AS `_veridelta_match_4` FROM `_src_normalized` AS `src` INNER JOIN `_tgt_normalized` AS `tgt` ON `src`.`code` = `tgt`.`code` WHERE NOT (COALESCE(`src`.`status` <=> `tgt`.`status`, FALSE) AND COALESCE(`src`.`city` <=> `tgt`.`city`, FALSE) AND COALESCE(`src`.`first` <=> `tgt`.`first`, FALSE) AND COALESCE(`src`.`last` <=> `tgt`.`last`, FALSE) AND COALESCE(`src`.`score` <=> `tgt`.`score`, FALSE)) ORDER BY `_veridelta_key_0` LIMIT 5
